      eyePaths += '<path d="' + leaf(e[0],e[1],e[2],e[3],e[4],e[5],e[6],e[7]) + '"/>';
      const ang = Math.atan2(e[3]-e[1], e[2]-e[0]) * 180 / Math.PI;
      [[.42,17,10],[.66,13,8]].forEach(function(b){
        const cx = e[0] + (e[2]-e[0]) * b[0], cy = e[1] + (e[3]-e[1]) * b[0];
        blots += '<ellipse cx="'+cx.toFixed(1)+'" cy="'+cy.toFixed(1)+'" rx="'+(b[1]*1.6)+'" ry="'+(b[2]*1.5)+
                 '" transform="rotate('+ang.toFixed(1)+' '+cx.toFixed(1)+' '+cy.toFixed(1)+')"/>';
      });
